CREATE TABLE shipment(id BIGINT PRIMARY KEY AUTO_INCREMENT,shipment_no VARCHAR(64) NOT NULL UNIQUE,order_no VARCHAR(64) NOT NULL UNIQUE,carrier VARCHAR(64) NOT NULL,tracking_no VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,stage INT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_no) REFERENCES trade_order(order_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE shipment_track(id BIGINT PRIMARY KEY AUTO_INCREMENT,shipment_no VARCHAR(64) NOT NULL,event_id VARCHAR(100) NOT NULL,event_time DATETIME(6) NOT NULL,status VARCHAR(32) NOT NULL,description VARCHAR(255) NOT NULL,UNIQUE(shipment_no,event_id),FOREIGN KEY(shipment_no) REFERENCES shipment(shipment_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mock_shipment(shipment_no VARCHAR(64) PRIMARY KEY,request_json LONGTEXT NOT NULL,fail_query BOOLEAN NOT NULL DEFAULT FALSE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mock_shipment_track(id BIGINT PRIMARY KEY AUTO_INCREMENT,shipment_no VARCHAR(64) NOT NULL,event_id VARCHAR(100) NOT NULL,event_time DATETIME(6) NOT NULL,status VARCHAR(32) NOT NULL,description VARCHAR(255) NOT NULL,UNIQUE(shipment_no,event_id),FOREIGN KEY(shipment_no) REFERENCES mock_shipment(shipment_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
